// Shapes of the static demo cache published at <BASE>/demo-cache/ (generated by
// scripts/ on the cache branch; see docs/FRONTEND_MODES.md).

export interface DemoScenarioMeta {
  id: string
  title: string
  description: string
  /** Path of the scenario JSON, relative to <BASE>/demo-cache/. */
  file: string
  endpoint?: string
  bytes?: number
  sha?: string
  /** 10-hex prefix of sha; appended as ?v= so a CDN can cache scenario files as immutable. */
  version?: string
}

export interface DemoIndex {
  version: number | string
  generated_at?: string
  engine_version?: string
  features: Record<string, DemoScenarioMeta[]>
}

/** One precomputed example: `response` is exactly what the live API returned for `request`. */
export interface DemoScenario<Req = unknown, Res = unknown> {
  id: string
  title: string
  description: string
  feature: string
  request: Req
  response: Res
  /** Which live endpoint produced this (e.g. /simulate, /simulate/ensemble, /sequence/lineage). */
  endpoint?: string
  meta?: Record<string, unknown>
  /** Feature-specific side data (experiments ledger: extra.details[run_id]). */
  extra?: Record<string, unknown>
}
